      AttributeOverride( name = "value", column = Column(name = "humidity_value"))
    )
    var humidity: Percent? = null,
    var station: WeatherStation? = null
)

data class DeleteWeatherObservationCommand(@Id  var id: UUID? = null)

// single association commands
data class AssignStationToWeatherObservationCommand(@Id  val parentId: UUID, val childId: UUID )
data class UnAssignStationFromWeatherObservationCommand(@Id  val parentId: UUID, val childId: UUID )

// multiple association commands




data class IdentifierRequest(
    val id: UUID
)

data class AssociationRequest(
    val parentId: UUID,
    val childId: UUID
)

data class MultipleAssociationRequest(
    val parentId: UUID,
    val childIds: List<UUID>
)